$ErrorActionPreference = "Stop"
$base64 = @'

'@ -replace '\s',''
$png = [Convert]::FromBase64String($base64)
$stream = [System.IO.MemoryStream]::new()
$writer = [System.IO.BinaryWriter]::new($stream)
$writer.Write([UInt16]0)
$writer.Write([UInt16]1)
$writer.Write([UInt16]1)
$writer.Write([Byte]128)
$writer.Write([Byte]128)
$writer.Write([Byte]0)
$writer.Write([Byte]0)
$writer.Write([UInt16]1)
$writer.Write([UInt16]32)
$writer.Write([UInt32]$png.Length)
$writer.Write([UInt32]22)
$writer.Write($png)
$writer.Flush()
$out = Join-Path $PSScriptRoot '..\MILTVPLUS.Desktop\miltvplus.ico'
[System.IO.File]::WriteAllBytes((Join-Path $PSScriptRoot '..\MILTVPLUS.Desktop\miltvplus.ico'), $stream.ToArray())
Write-Host "Generated MILTVPLUS icon: $out"
